	@Test
	void standardPipelineRetainsReachableVolatileCallsBesideLogicalConstants() throws Exception {
		AtomicInteger calls = new AtomicInteger();
		Function function = new Function() {
			@Override
			public String getURI() {
				return "urn:scoped-union:volatile-predicate";
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.VOLATILE;
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... arguments) {
				calls.incrementAndGet();
				return BooleanLiteral.FALSE;
			}
		};
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.get(function.getURI()).orElse(null);
		registry.add(function);
		try {
			for (QueryEvaluationMode mode : QueryEvaluationMode.values()) {
				for (QueryExecutionPolicy policy : List.of(QueryExecutionPolicy.DEFAULT,
						QueryExecutionPolicy.EXPERIMENTAL)) {
					for (String logical : List.of(" || true", " && false")) {
						TupleExpr original = parse(
								"SELECT * WHERE { { VALUES ?x { 1 2 } } UNION { VALUES ?x { 3 } } FILTER(<"
										+ function.getURI() + ">()" + logical + ") }");
						DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(),
								null);
						strategy.setQueryEvaluationMode(mode);
						strategy.setQueryExecutionPolicy(policy);
						TupleExpr optimized = strategy.optimize(original.clone(), new EvaluationStatistics(),
								EmptyBindingSet.getInstance());
						calls.set(0);
						try (CloseableIteration<BindingSet> rows = strategy.evaluate(optimized,
								EmptyBindingSet.getInstance())) {
							assertThat(rows.stream().count()).isEqualTo(logical.contains("true") ? 3 : 0);
						}
						assertThat(calls.get()).as("reachable calls in %s, experimental=%s, %s", mode,
								policy.experimentalQueryOptimizations(), logical).isEqualTo(3);
					}
				}
			}
		} finally {
			registry.remove(function);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void compileTimeConditionErrorStillEvaluatesFatalServiceArgument(boolean optimize) throws Exception {
		String regex = optimize ? "REGEX(?text, ?pattern)" : "REGEX(\"text\", <urn:invalid-pattern>)";
		TupleExpr root = parse("SELECT * WHERE { VALUES (?text ?pattern) { (\"text\" <urn:invalid-pattern>) } "
				+ "SERVICE <urn:required-service> { ?s ?p ?o } FILTER(" + regex + ") }");
		AtomicInteger serviceCalls = new AtomicInteger();
		FederatedService remote = mock(FederatedService.class);
		when(remote.isInitialized()).thenReturn(true);
		when(remote.select(any(), anySet(), any(), any())).thenAnswer(call -> new LookAheadIteration<BindingSet>() {
			@Override
			protected BindingSet getNextElement() {
				serviceCalls.incrementAndGet();
				throw new QueryEvaluationException("required-service-failure");
			}

			@Override
			protected void handleClose() {
			}
		});
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), endpoint -> remote);
		if (optimize) {
			new FilterOptimizer(null, false, false, strategy).optimize(root, null, EmptyBindingSet.getInstance());
		}
		assertThatThrownBy(() -> {
			try (var rows = strategy.evaluate(root, EmptyBindingSet.getInstance())) {
				rows.hasNext();
			}
		}).as("constant condition error, simplified=%s", optimize)
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("required-service-failure");
		assertThat(serviceCalls.get()).as("failure occurs while consuming the required remote argument").isEqualTo(1);
	}

	@Test
	void movingAGroupRootFilterKeepsTheBoundaryAboveAnExtension() throws Exception {
		Coalesce value = new Coalesce();
		value.addArgument(Var.of("outer"));
		value.addArgument(constant(2));
		Extension extension = new Extension(values("x", 1, 2), new ExtensionElem(value, "z"));
		Filter filter = new Filter(extension, new Compare(Var.of("x"), constant(1), Compare.CompareOp.GT));
		filter.setVariableScopeChange(true);
		QueryRoot root = new QueryRoot(new Join(values("outer", 1), filter));
		List<BindingSet> expected = evaluate(root.clone());
		assertThat(expected).singleElement()
				.satisfies(row -> assertThat(row.getValue("z"))
						.isEqualTo(SimpleValueFactory.getInstance().createLiteral(2)));
		new FilterOptimizer(null, false, false).optimize(root, null, EmptyBindingSet.getInstance());
		assertThat(extension.isVariableScopeChange()).isTrue();
		assertThat(evaluate(root)).containsExactlyInAnyOrderElementsOf(expected);
	}

