	@Test
	void pruningEliminatesRejectedBranchWork() throws Exception {
		TupleExpr original = parse("SELECT * WHERE { { VALUES ?x { 1 } } UNION { ?s <urn:p> ?y } FILTER(BOUND(?x)) }");
		AtomicInteger probes = new AtomicInteger();
		EmptyTripleSource counting = new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				probes.incrementAndGet();
				return super.getStatements(subject, predicate, object, contexts);
			}
		};
		List<BindingSet> expected = evaluate(original.clone(), EmptyBindingSet.getInstance(), counting);
		assertThat(probes.get()).isPositive();
		TupleExpr optimized = original.clone();
		new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());
		probes.set(0);
		assertThat(evaluate(optimized, EmptyBindingSet.getInstance(), counting))
				.containsExactlyInAnyOrderElementsOf(expected);
		assertThat(probes.get()).as("known-unbound arm is never evaluated").isZero();
	}

	@Test
	void nestedCompositionsPreserveBagsAndReachStablePruningInOnePass() throws Exception {
		List<String> bodies = List.of(
				"{ VALUES ?x { 1 1 2 UNDEF } } UNION { VALUES ?y { 3 } } FILTER(BOUND(?x))",
				"{ { VALUES ?x { 1 1 } } UNION { VALUES ?y { 2 } } FILTER(BOUND(?x)) } UNION { VALUES ?z { 3 } } FILTER(BOUND(?x))",
				"{ VALUES ?x { 1 2 } OPTIONAL { VALUES ?y { 2 } FILTER(?x = ?y) } } UNION { VALUES ?x { 3 } } FILTER(?x > 1)",
				"{ VALUES ?x { 1 2 2 } MINUS { VALUES ?x { 1 } } } UNION { VALUES ?x { 3 } } FILTER(?x > 1)",
				"{ SELECT ?x WHERE { VALUES ?x { 1 2 2 } } } UNION { VALUES ?y { 3 } } FILTER(COALESCE(?x > 1, false))",
				"{ VALUES ?x { 1 2 } } UNION { VALUES ?y { 3 } } FILTER EXISTS { VALUES ?x { 2 } }",
				"{ VALUES ?x { 1 2 } } UNION { VALUES ?y { 3 } } FILTER NOT EXISTS { VALUES ?x { 2 } }",
				"{ VALUES ?x { 1 2 } } UNION { VALUES ?y { 3 } } FILTER(IF(BOUND(?x), ?x > 1, true))",
				"{ VALUES ?x { 1 } } UNION { VALUES ?y { 3 } } FILTER(COALESCE(<urn:iri>, true))");
		for (String body : bodies) {
			TupleExpr original = parse("SELECT * WHERE { " + body + " }");
			List<BindingSet> expected = evaluate(original.clone());
			TupleExpr optimized = original.clone();
			new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());
			assertThat(evaluate(optimized.clone())).as(body).containsExactlyInAnyOrderElementsOf(expected);
			TupleExpr stable = optimized.clone();
			new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());
			assertThat(optimized).as("one pass is stable: %s", body).isEqualTo(stable);
		}
	}

	@Test
	void distributesFilterAcrossScopedUnionArmsAndPreservesBagResults() throws Exception {
		String query = """
				SELECT ?arm ?x WHERE {
				  { VALUES (?arm ?x) { ("left" 1) ("left" 2) ("left" 2) } }
				  UNION
				  { VALUES (?arm ?x) { ("right" 1) ("right" 2) } }
				  FILTER(?x > 1)
				}
				""";

		TupleExpr original = parse(query);
		Union originalUnion = findOnlyUnion(original);
		assertThat(originalUnion.isVariableScopeChange()).as("parsed UNION starts with a new variable scope")
				.isTrue();
		List<BindingSet> expected = evaluate(original.clone());
		assertThat(expected).hasSize(3);

		TupleExpr optimized = original.clone();
		new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());

		Union optimizedUnion = findOnlyUnion(optimized);
		assertThat(optimizedUnion.isVariableScopeChange()).as("optimization preserves the UNION scope marker").isTrue();
		assertThat(filtersIn(optimizedUnion.getLeftArg())).as("the left arm receives its own filter").hasSize(1);
		assertThat(filtersIn(optimizedUnion.getRightArg())).as("the right arm receives its own filter").hasSize(1);
		assertThat(filtersIn(optimized)).as("the parent filter is replaced by a complete UNION cut").hasSize(2);
		assertThat(evaluate(optimized)).containsExactlyInAnyOrderElementsOf(expected);
	}

	@Test
	void prunesUnionArmWhenFilterVariableIsKnownUnboundAndKeepsProjectedSchema() throws Exception {
		String query = """
				SELECT * WHERE {
				  { VALUES ?x { 1 1 } }
				  UNION
				  { VALUES ?y { 2 3 } }
				  FILTER(BOUND(?x))
				}
				""";

		TupleExpr original = parse(query);
		Union originalUnion = findOnlyUnion(original);
		assertThat(originalUnion.isVariableScopeChange()).as("parsed UNION starts with a new variable scope")
				.isTrue();
		List<BindingSet> expected = evaluate(original.clone());
		assertThat(expected).hasSize(2);
		assertThat(expected).allSatisfy(row -> {
			assertThat(row.hasBinding("x")).isTrue();
			assertThat(row.hasBinding("y")).isFalse();
		});

		TupleExpr optimized = original.clone();
		new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());

		Union optimizedUnion = findOnlyUnion(optimized);
		assertThat(optimizedUnion.getBindingNames()).contains("x", "y");
		assertThat(isKnownEmpty(optimizedUnion.getLeftArg()) || isKnownEmpty(optimizedUnion.getRightArg()))
				.as("the arm where ?x is known unbound must be represented as empty while retaining UNION names")
				.isTrue();
		List<BindingSet> actual = evaluate(optimized);
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(actual).allSatisfy(row -> {
			assertThat(row.hasBinding("x")).isTrue();
			assertThat(row.hasBinding("y")).isFalse();
		});
	}

	@Test
	void preservesCorrelatedInputAtMarkedUnionInsideExists() throws Exception {
		String query = """
				SELECT ?outer WHERE {
				  VALUES ?outer { 1 }
				  FILTER EXISTS {
				    { FILTER(BOUND(?outer)) }
				    UNION
				    { FILTER(false) }
				  }
				}
				""";

		TupleExpr original = parse(query);
		Union union = findOnlyUnion(original);
		assertThat(union.isVariableScopeChange()).as("parsed UNION starts with a new variable scope").isTrue();
		List<BindingSet> expected = evaluate(original.clone());
		assertThat(expected).hasSize(1);

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(original,
				EmptyBindingSet.getInstance());
		assertThat(analysis.bindingState(Var.of("outer"), analysis.contextAt(union.getLeftArg())))
				.as("the EXISTS-correlated row is still bound when UNION enters its branch")
				.isEqualTo(
						QueryAlgebraBindingAnalysis.BindingState.BOUND);

		TupleExpr optimized = original.clone();
		new FilterOptimizer(null, false, false).optimize(optimized, null, EmptyBindingSet.getInstance());
		assertThat(evaluate(optimized)).containsExactlyInAnyOrderElementsOf(expected);
	}

	private static TupleExpr parse(String query) throws Exception {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private static Union findOnlyUnion(TupleExpr expression) {
		List<Union> unions = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				unions.add(union);
				super.meet(union);
			}
		});
		assertThat(unions).hasSize(1);
		return unions.getFirst();
	}

	private static List<Filter> filtersIn(QueryModelNode expression) {
		List<Filter> filters = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				filters.add(filter);
				super.meet(filter);
			}
		});
		return filters;
	}

	private static boolean isKnownEmpty(TupleExpr expression) {
		if (expression instanceof EmptySet) {
			return true;
		}
		if (expression instanceof BindingSetAssignment assignment) {
			return !assignment.getBindingSets().iterator().hasNext();
		}
		return false;
	}

	private static List<BindingSet> evaluate(TupleExpr expression) throws Exception {
		return evaluate(expression, EmptyBindingSet.getInstance(), new EmptyTripleSource());
	}

	private static List<BindingSet> evaluate(TupleExpr expression, BindingSet input, EmptyTripleSource source)
			throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, input)) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private static ValueConstant constant(int value) {
		return new ValueConstant(SimpleValueFactory.getInstance().createLiteral(value));
	}

	private static BindingSetAssignment values(String name, int... values) {
		List<BindingSet> rows = new ArrayList<>();
		for (int value : values) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding(name, SimpleValueFactory.getInstance().createLiteral(value));
			rows.add(row);
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of(name));
		assignment.setBindingSets(rows);
		return assignment;
	}
